/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,16],[16,32],[32,72],[72,82]]);
  var np = 0, nd = 0;
  for (var i = 0; i < 12; i++) {
    var a = lin([[2 + i * 0.8, 0],[4 + i * 0.8, 1]]);
    var t = 34 + i * 3, f = lin([[t,0],[t+2.5,1]]);
    var tx = (268 - (18 + (i % 4) * 62)) * f, ty = ((i % 2 ? 150 : 40) - (16 + Math.floor(i / 4) * 74)) * f;
    v['sh'+i] = 'opacity: ' + (a * (1 - 0.85 * f) * out).toFixed(3) + '; transform: translate(' + tx.toFixed(1) + 'px,' + ty.toFixed(1) + 'px) scale(' + (1 - 0.4 * f).toFixed(3) + ');';
    if (p >= t + 2.5) { np++; nd++; }
  }
  v.np = np; v.nd = nd;
  v.oO = lin([[30,0],[34,1]]) * out;
  v.k0 = p >= 10 ? out : 0.25 * out; v.k1 = p >= 18 ? out : 0.25 * out; v.k2 = p >= 24 ? out : 0.25 * out; v.k3 = p >= 30 ? out : 0.25 * out;
  v.fin = (p >= 74 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
